/**
 * XPLOITX // CYBER BATTLEFIELD
 * AgentPairingCode Model (backend/models/AgentPairingCode.js)
 * Short-lived one-time codes generated by Admin for agent pairing.
 */

const mongoose = require('mongoose');

const pairingCodeSchema = new mongoose.Schema({
  code:        { type: String, required: true, unique: true, index: true },
  generatedBy: { type: String, required: true },   // Admin userId
  createdAt:   { type: Date, default: Date.now },
  expiresAt:   { type: Date, required: true },
  used:        { type: Boolean, default: false, index: true },
  usedByAgentId: { type: String, default: null }
});

// Auto-delete expired documents after TTL
pairingCodeSchema.index({ expiresAt: 1 }, { expireAfterSeconds: 0 });

module.exports = mongoose.models.AgentPairingCode ||
  mongoose.model('AgentPairingCode', pairingCodeSchema);
